import {pool,makeState,box,active,point,concentration,immersed,clipToVessel,physicsFor,EPS,take,add,transfer,updateParents} from './measurement-common.js';
export * from './measurement-common.js';
// Limiting-conductivity approximation at 25°C; concentration corrections are omitted.
export const CONDUCTIVITY={NaCl:126.4,hcl:426,acidIons:390.5,Ka:1.8e-5,water:.000055};
export function createState(){const items={
 salt:pool('salt','NaCl · 0.100 M',140,429,80,{NaCl:.008}),sugar:pool('sugar','Sucrose · 0.100 M',260,429,80,{sucrose:.008}),acid:pool('acid','HCl · 0.100 M',380,429,80,{hcl:.008}),weak:pool('weak','CH₃COOH · 0.100 M',500,429,80,{ethanoic:.008}),
 sample:pool('sample','Test beaker',620,429),water:pool('water','Deionised water',870,429,500,{},600),dry:pool('dry','Solid sodium chloride',90,100),waste:pool('waste','Waste beaker',180,100,0,{},1000),
 meter:{id:'meter',name:'Conductivity meter',kind:'conductivityMeter',x:745,y:445,angle:0,on:false,collision:[box(0,40,145,80)],mass:3},
 electrodeA:{...pool('electrodeA','Probe A',300,100),kind:'electrode',collision:[box(0,45,8,90)],capacity:.05},electrodeB:{...pool('electrodeB','Probe B',400,100),kind:'electrode',collision:[box(0,45,8,90)],capacity:.05}
 };items.dry.solidNaCl=.005;return makeState('conductivity',items);}
export function conductivity(o){const c=concentration(o,'ethanoic'),strong=concentration(o,'hcl'),a=(-(strong+CONDUCTIVITY.Ka)+Math.sqrt((strong+CONDUCTIVITY.Ka)**2+4*CONDUCTIVITY.Ka*c))/2;return CONDUCTIVITY.water+CONDUCTIVITY.NaCl*concentration(o,'NaCl')+CONDUCTIVITY.hcl*strong+CONDUCTIVITY.acidIons*a;}
export function reading(s){const m=s.items.meter;if(!active(m)||!m.on)return{value:null,status:'Meter off.'};const a=s.leads.red,b=s.leads.black;if(!a||!b||a===b||!active(s.items[a])||!active(s.items[b]))return{value:null,status:'Connect the two lead ends to different probes.'};const tips=[point(s.items[a],0,85),point(s.items[b],0,85)],dry=Object.values(s.items).find(o=>active(o)&&o.kind==='beaker'&&o.solidNaCl>EPS&&o.water<=EPS&&tips.every(p=>Math.abs(p.x-o.x)<28&&p.y>=o.y+74&&p.y<=o.y+94));if(dry){if(s.items[a].water>EPS||s.items[b].water>EPS)return{value:null,status:'Retained liquid films invalidate a dry-solid comparison. Clean and drain the probes first.'};return{value:0,sample:dry.id,cellConstant:null,conductivity:0,status:'Dry solid contact · lattice ions are not mobile in this model.'};}const x=immersed(s,a),y=immersed(s,b);if(!x||x!==y)return{value:null,status:'Both probe tips must contact the same liquid. A dry sample has no mobile ions; an open contact cannot establish its conductivity.'};
 const p=point(s.items[a],0,85),q=point(s.items[b],0,85),gap=Math.max(8,Math.hypot(p.x-q.x,p.y-q.y)),surface=x.y+86-72*Math.min(1,x.water/x.capacity),depth=Math.max(1,Math.min(p.y,q.y)-surface),cellConstant=gap/24*30/Math.min(60,depth),value=conductivity(x)/cellConstant;
 return{value,sample:x.id,cellConstant,conductivity:conductivity(x),status:'Liquid circuit complete · keep probe spacing and depth consistent.'};}
function exchangeFilm(s,id,b){const o=s.items[id];if(o.lastSample===b.id)return;if(o.water>EPS)add(b,take(o,o.water));if(b.water>EPS)add(o,take(b,Math.min(.05,b.water)));o.lastSample=b.id;}
export function clip(s,id){const o=s.items[id];if(!active(o)||!['electrodeA','electrodeB'].includes(id))return false;const b=clipToVessel(s,id,id==='electrodeA'?-12:12);if(!b)return false;if(b.solidNaCl>EPS&&b.water<=EPS){o.offset.y=-6;updateParents(s);}const contact=immersed(s,id);if(contact)exchangeFilm(s,id,contact);return true;}
export function rinse(s,id){const o=s.items[id],w=s.items.water,b=s.items.waste;if(s.phase!=='working'||!active(o)||o.parent||!active(w)||!active(b)||Math.abs(o.x-b.x)>70||Math.abs(o.y-b.y)>180||Math.abs(o.x-w.x)>230||w.water<2)return false;add(b,take(o,o.water));o.lastSample=null;transfer(s,'water','waste',2);return true;}
export const formatConductance=value=>value.toFixed(value<1?5:3);
export function record(s){if(s.phase!=='working')return null;const r=reading(s);if(r.value===null)return null;const row={...r,time:s.time,name:s.items[r.sample].name,volume:s.items[r.sample].water,value:Number(formatConductance(r.value)),cellConstant:r.cellConstant===null?null:Number(r.cellConstant.toFixed(4))};s.records.push(row);return row;}
export function stepChemistry(s,dt){if(s.phase!=='working'||!Number.isFinite(dt)||dt<=0)return;s.time+=dt;for(const id of ['electrodeA','electrodeB']){const o=s.items[id];if(!active(o)){o.lastSample=null;continue;}const b=immersed(s,id);if(b)exchangeFilm(s,id,b);else o.lastSample=null;}}
